# Remind an OPEN or PENDING claim: it shows the sheet's today as its reminded date. Once per
# sheet-today: a second reminder the same day, or a claim in any other status, is a 409 and writes
# nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimRemind
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimRemind
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimReminded
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused reminder writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimRemind {
    public void validate(@RequestBody ClaimRemindRequest request, Out<ClaimRemind> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        if (user.isEmpty()) throw new InvalidSheetRequestException("Who reminds the claim must be named");
        actor.set(new Actor(user));
        body.set(new ClaimRemind(user));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Reminds an OPEN or PENDING claim on the sheet's today, once per sheet-today. A claim in any other
 *  status, or one already reminded on the sheet's today, is refused. */
public class ApplyClaimRemind {
    public void apply(@Val ClaimRemind change, @Val Claim claim, Sheets sheets) throws ClaimStatusRefusedException {
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be reminded");
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (today.equals(claim.getRemindedOn())) {
            throw new ClaimStatusRefusedException("The claim has already been reminded on " + today);
        }
        claim.setRemindedOn(today);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaimReminded {
    public void save(@Val Claim claim, Claims claims) {
        claims.remind(claim);
    }
}
package net.officefloor.hq.app.claim;

/** A claim being reminded by `user`. */
public record ClaimRemind(String user) {
}
-- An OPEN or PENDING claim may be reminded, once per sheet-today: the last day a reminder was
-- written. Null: never reminded.
ALTER TABLE public.claim ADD COLUMN reminded_on DATE;
